from __future__ import annotations

import argparse
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any
from urllib.parse import urlsplit

from .errors import NotFoundError, ThresholdSafeError, ValidationError
from .service import ThresholdSafe


class Handler(BaseHTTPRequestHandler):
    service: ThresholdSafe

    def log_message(self, format: str, *args: Any) -> None:
        return

    def _json(self, status: int, value: Any) -> None:
        body = json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _body(self) -> Any:
        if self.headers.get("Content-Type", "").split(";", 1)[0].strip().lower() != "application/json":
            raise ValidationError("Content-Type must be application/json")
        try:
            length = int(self.headers.get("Content-Length", "0"))
            if length < 0 or length > 1_000_000:
                raise ValueError
            return json.loads(self.rfile.read(length))
        except (ValueError, json.JSONDecodeError) as error:
            raise ValidationError("request body must be valid JSON") from error

    def _dispatch(self) -> tuple[int, Any]:
        parts = [part for part in urlsplit(self.path).path.split("/") if part]
        key = self.headers.get("Idempotency-Key")
        if self.command == "GET" and parts == ["health"]:
            return 200, {"status": "ok"}
        if self.command == "POST" and parts == ["secrets"]:
            return 201, self.service.create_secret(self._body(), key)
        if len(parts) == 2 and parts[0] == "secrets" and self.command == "GET":
            return 200, self.service.get_secret(parts[1])
        if self.command == "POST" and parts == ["backups", "verify"]:
            return 200, self.service.verify_backup(self._body())
        if len(parts) == 3 and parts[0] == "secrets":
            if parts[2] == "audit" and self.command == "GET":
                return 200, self.service.audit(parts[1])
            if parts[2] == "backup" and self.command == "GET":
                return 200, self.service.export_backup(parts[1])
            if parts[2] == "policy" and self.command == "GET":
                return 200, self.service.get_policy(parts[1])
            if self.command == "POST":
                body = self._body()
                actions = {
                    "shares": (201, self.service.distribute_share),
                    "approvals": (201, self.service.record_approval),
                    "reconstruct": (200, self.service.reconstruct),
                    "rotate": (200, self.service.rotate),
                    "freeze": (200, self.service.freeze_secret),
                    "unfreeze": (200, self.service.unfreeze_secret),
                }
                if parts[2] in actions:
                    status, action = actions[parts[2]]
                    return status, action(parts[1], body, key)
        raise NotFoundError("route was not found")

    def _handle(self) -> None:
        try:
            status, response = self._dispatch()
            self._json(status, response)
        except ThresholdSafeError as error:
            self._json(error.status, {"error": {"code": error.code, "message": str(error)}})
        except Exception:
            self._json(500, {"error": {"code": "internal_error", "message": "internal server error"}})

    do_GET = _handle
    do_POST = _handle


def main() -> None:
    parser = argparse.ArgumentParser(description="Run the ThresholdSafe HTTP service")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", default=8080, type=int)
    parser.add_argument("--database", default="thresholdsafe.db")
    arguments = parser.parse_args()
    Handler.service = ThresholdSafe(arguments.database)
    server = ThreadingHTTPServer((arguments.host, arguments.port), Handler)
    print(f"ThresholdSafe listening on http://{arguments.host}:{arguments.port}", flush=True)
    server.serve_forever()


if __name__ == "__main__":
    main()

from __future__ import annotations

import json
import sqlite3
import threading
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Iterator

SCHEMA = """
CREATE TABLE IF NOT EXISTS secrets (
  id TEXT PRIMARY KEY,
  document TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS shares (
  share_id TEXT PRIMARY KEY,
  secret_id TEXT NOT NULL REFERENCES secrets(id),
  version INTEGER NOT NULL,
  holder TEXT NOT NULL,
  coordinate INTEGER NOT NULL,
  value TEXT NOT NULL,
  commitment TEXT NOT NULL,
  distributed_at TEXT,
  invalidated_at TEXT,
  UNIQUE (secret_id, version, holder)
);
CREATE TABLE IF NOT EXISTS approvals (
  secret_id TEXT NOT NULL REFERENCES secrets(id),
  version INTEGER NOT NULL,
  approver TEXT NOT NULL,
  created_at TEXT NOT NULL,
  consumed_at TEXT,
  PRIMARY KEY (secret_id, version, approver)
);
CREATE TABLE IF NOT EXISTS audit_events (
  secret_id TEXT NOT NULL REFERENCES secrets(id),
  sequence INTEGER NOT NULL,
  type TEXT NOT NULL,
  payload TEXT NOT NULL,
  occurred_at TEXT NOT NULL,
  previous_hash TEXT NOT NULL,
  hash TEXT NOT NULL,
  PRIMARY KEY (secret_id, sequence)
);
CREATE TABLE IF NOT EXISTS idempotency (
  key TEXT PRIMARY KEY,
  operation TEXT NOT NULL,
  response TEXT NOT NULL
);
"""


class Store:
    def __init__(self, path: str):
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        self.path = path
        self._local = threading.local()
        # Create the schema eagerly so the file is fully initialised even when
        # worker threads later open their own connections.
        self._open()

    def _open(self) -> sqlite3.Connection:
        connection = sqlite3.connect(self.path, isolation_level=None, timeout=10)
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA foreign_keys = ON")
        connection.execute("PRAGMA busy_timeout = 10000")
        connection.execute("PRAGMA journal_mode = WAL")
        connection.executescript(SCHEMA)
        self._local.connection = connection
        return connection

    @property
    def connection(self) -> sqlite3.Connection:
        connection = getattr(self._local, "connection", None)
        if connection is None:
            connection = self._open()
        return connection

    @contextmanager
    def transaction(self) -> Iterator[sqlite3.Connection]:
        connection = self.connection
        connection.execute("BEGIN IMMEDIATE")
        try:
            yield connection
        except Exception:
            connection.execute("ROLLBACK")
            raise
        else:
            connection.execute("COMMIT")

    @staticmethod
    def encode(value: Any) -> str:
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"), sort_keys=True)

    @staticmethod
    def decode(value: str) -> Any:
        return json.loads(value)

    @staticmethod
    def now() -> str:
        return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")

"""Self-contained backup format and its independent verifier.

A backup exported by ``ThresholdSafe.export_backup`` carries everything needed
to reconstruct the custody state of one secret — the secret record (without
the plaintext secret), the persistent authorization policy, every share of
every version, all approvals and the full audit stream — plus a SHA-256
checksum over the remaining top-level values. ``verify`` re-checks such a
document without touching any service state: structural problems raise
:class:`ValidationError`, while a well-formed document whose contents are
inconsistent raises :class:`BackupIntegrity`.

Two formats are accepted. ``thresholdsafe-backup-v1`` is the original layout
and is verified unchanged. ``thresholdsafe-backup-v2`` adds the top-level
``authorization_policy`` field (a policy expression or ``null``), which is
covered by the checksum. ``thresholdsafe-backup-v3`` — what new exports
produce — adds ``versions``: a snapshot of the holder and approver rosters of
every version from 1 to the current one, so the role attribution of each
share and approval can be verified against the version it belongs to. v1 and
v2 documents carry no role information and are read in legacy mode, where the
approvers of a version are exactly its holders.
"""

from __future__ import annotations

import hashlib
import json
import re
from typing import Any

from .errors import BackupIntegrity, ValidationError
from .model import identifier, positive_int
from .policy import parse_policy

BACKUP_VERSION_V1 = "thresholdsafe-backup-v1"
BACKUP_VERSION_V2 = "thresholdsafe-backup-v2"
BACKUP_VERSION_V3 = "thresholdsafe-backup-v3"
BACKUP_VERSION = BACKUP_VERSION_V3
ZERO_HASH = "0" * 64
HEX_HASH = re.compile(r"^[0-9a-f]{64}$")
SHARE_VALUE = re.compile(r"^[0-9a-f]{1,132}$")

TOP_LEVEL_FIELDS = {
    "backup_version",
    "generated_at",
    "secret",
    "shares",
    "approvals",
    "audit_events",
    "checksum",
}
TOP_LEVEL_FIELDS_V2 = TOP_LEVEL_FIELDS | {"authorization_policy"}
TOP_LEVEL_FIELDS_V3 = TOP_LEVEL_FIELDS_V2 | {"versions"}
SECRET_FIELDS = {
    "id",
    "name",
    "version",
    "threshold",
    "holders",
    "approvals_required",
    "secret_digest",
    "secret_length",
    "status",
    "status_reason",
    "status_changed_at",
    "status_epoch",
    "created_at",
    "updated_at",
}
SHARE_FIELDS = {
    "share_id",
    "secret_id",
    "version",
    "holder",
    "coordinate",
    "value",
    "commitment",
    "distributed_at",
    "invalidated_at",
}
APPROVAL_FIELDS = {"secret_id", "version", "approver", "created_at", "consumed_at"}
EVENT_FIELDS = {"sequence", "type", "payload", "occurred_at", "previous_hash", "hash"}
VERSION_ENTRY_FIELDS = {"version", "approval_mode", "holders", "approvers"}
APPROVAL_MODES = ("legacy", "separated")


def encode(value: Any) -> str:
    """Canonical JSON: sorted keys, compact separators, no ASCII escaping."""
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"), sort_keys=True)


def share_commitment(secret_id: str, version: int, holder: str, value: str) -> str:
    return hashlib.sha256(
        f"thresholdsafe:v1:share:{secret_id}:{version}:{holder}:{value}".encode()
    ).hexdigest()


def event_hash(previous: str, sequence: int, event_type: str, encoded: str, occurred_at: str) -> str:
    return hashlib.sha256(f"{previous}|{sequence}|{event_type}|{encoded}|{occurred_at}".encode()).hexdigest()


def checksum(unsigned: dict[str, Any]) -> str:
    """SHA-256 of the canonical encoding of every top-level value but the checksum."""
    return hashlib.sha256(encode(unsigned).encode()).hexdigest()


def stamp(backup: dict[str, Any]) -> dict[str, Any]:
    """Attach the checksum covering the other top-level values of a backup."""
    backup["checksum"] = checksum(backup)
    return backup


# ------------------------------------------------------------------ structure
def _require_object(raw: Any, fields: set[str], description: str) -> dict[str, Any]:
    if not isinstance(raw, dict):
        raise ValidationError(f"{description} must be an object")
    missing = sorted(fields - set(raw))
    if missing:
        raise ValidationError(f"{description} is missing required fields: {', '.join(missing)}")
    extra = sorted(set(raw) - fields)
    if extra:
        raise ValidationError(f"{description} does not allow these fields: {', '.join(extra)}")
    return raw


def _non_empty_text(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value:
        raise ValidationError(f"{field} must be a non-empty string")
    return value


def _optional_text(value: Any, field: str) -> str | None:
    if value is not None and not isinstance(value, str):
        raise ValidationError(f"{field} must be a string or null")
    return value


def _hash_text(value: Any, field: str) -> str:
    if not isinstance(value, str) or not HEX_HASH.match(value):
        raise ValidationError(f"{field} must be a lowercase hexadecimal SHA-256 digest")
    return value


def _parse_secret(raw: Any) -> dict[str, Any]:
    secret = _require_object(raw, SECRET_FIELDS, "secret")
    identifier(secret["id"], "secret id")
    _non_empty_text(secret["name"], "secret name")
    positive_int(secret["version"], "secret version", 1)
    positive_int(secret["threshold"], "secret threshold", 2)
    positive_int(secret["approvals_required"], "secret approvals_required", 1)
    holders = secret["holders"]
    if not isinstance(holders, list) or not holders or any(not isinstance(h, str) for h in holders):
        raise ValidationError("secret holders must be a non-empty array of holder identifiers")
    if len(set(holders)) != len(holders):
        raise ValidationError("secret holders must not repeat the same holder")
    _hash_text(secret["secret_digest"], "secret_digest")
    positive_int(secret["secret_length"], "secret_length", 1)
    if secret["status"] not in ("active", "frozen"):
        raise ValidationError("secret status must be active or frozen")
    _optional_text(secret["status_reason"], "status_reason")
    epoch = secret["status_epoch"]
    if isinstance(epoch, bool) or not isinstance(epoch, int) or epoch < 0:
        raise ValidationError("status_epoch must be a non-negative integer")
    _non_empty_text(secret["status_changed_at"], "status_changed_at")
    _non_empty_text(secret["created_at"], "created_at")
    _non_empty_text(secret["updated_at"], "updated_at")
    return secret


def _parse_share(raw: Any) -> dict[str, Any]:
    share = _require_object(raw, SHARE_FIELDS, "share")
    identifier(share["share_id"], "share_id", limit=250)
    identifier(share["secret_id"], "share secret_id")
    identifier(share["holder"], "share holder")
    positive_int(share["version"], "share version", 1)
    positive_int(share["coordinate"], "share coordinate", 1)
    value = share["value"]
    if not isinstance(value, str) or not SHARE_VALUE.match(value):
        raise ValidationError("share value must be lowercase hexadecimal of at most 132 characters")
    _hash_text(share["commitment"], "share commitment")
    _optional_text(share["distributed_at"], "distributed_at")
    _optional_text(share["invalidated_at"], "invalidated_at")
    return share


def _parse_approval(raw: Any) -> dict[str, Any]:
    approval = _require_object(raw, APPROVAL_FIELDS, "approval")
    identifier(approval["secret_id"], "approval secret_id")
    identifier(approval["approver"], "approver")
    positive_int(approval["version"], "approval version", 1)
    _non_empty_text(approval["created_at"], "created_at")
    _optional_text(approval["consumed_at"], "consumed_at")
    return approval


def _parse_event(raw: Any) -> dict[str, Any]:
    event = _require_object(raw, EVENT_FIELDS, "audit event")
    positive_int(event["sequence"], "event sequence", 1)
    _non_empty_text(event["type"], "event type")
    if not isinstance(event["payload"], dict):
        raise ValidationError("event payload must be an object")
    _non_empty_text(event["occurred_at"], "occurred_at")
    _hash_text(event["previous_hash"], "event previous_hash")
    _hash_text(event["hash"], "event hash")
    return event


def _parse_version_entry(raw: Any) -> dict[str, Any]:
    entry = _require_object(raw, VERSION_ENTRY_FIELDS, "versions entry")
    positive_int(entry["version"], "versions entry version", 1)
    if entry["approval_mode"] not in APPROVAL_MODES:
        raise ValidationError("versions entry approval_mode must be legacy or separated")
    for field in ("holders", "approvers"):
        values = entry[field]
        if not isinstance(values, list) or not values:
            raise ValidationError(f"versions entry {field} must be a non-empty array of identifiers")
        for value in values:
            identifier(value, f"versions entry {field} entry")
        if len(set(values)) != len(values):
            raise ValidationError(f"versions entry {field} must not repeat the same identifier")
    return entry


def _parse(backup: Any) -> dict[str, Any]:
    if not isinstance(backup, dict):
        raise ValidationError("backup must be an object")
    version = backup.get("backup_version")
    if version == BACKUP_VERSION_V1:
        fields = TOP_LEVEL_FIELDS
    elif version == BACKUP_VERSION_V2:
        fields = TOP_LEVEL_FIELDS_V2
    elif version == BACKUP_VERSION_V3:
        fields = TOP_LEVEL_FIELDS_V3
    else:
        raise ValidationError(
            f"backup_version must be {BACKUP_VERSION_V1}, {BACKUP_VERSION_V2} or {BACKUP_VERSION_V3}"
        )
    document = _require_object(backup, fields, "backup")
    _non_empty_text(document["generated_at"], "generated_at")
    _hash_text(document["checksum"], "checksum")
    if version in (BACKUP_VERSION_V2, BACKUP_VERSION_V3) and document["authorization_policy"] is not None:
        parse_policy(document["authorization_policy"])
    shares = document["shares"]
    if not isinstance(shares, list):
        raise ValidationError("shares must be an array")
    approvals = document["approvals"]
    if not isinstance(approvals, list):
        raise ValidationError("approvals must be an array")
    events = document["audit_events"]
    if not isinstance(events, list):
        raise ValidationError("audit_events must be an array")
    versions: list[dict[str, Any]] | None = None
    if version == BACKUP_VERSION_V3:
        entries = document["versions"]
        if not isinstance(entries, list) or not entries:
            raise ValidationError("versions must be a non-empty array")
        versions = [_parse_version_entry(entry) for entry in entries]
    return {
        "raw": document,
        "secret": _parse_secret(document["secret"]),
        "versions": versions,
        "shares": [_parse_share(entry) for entry in shares],
        "approvals": [_parse_approval(entry) for entry in approvals],
        "audit_events": [_parse_event(entry) for entry in events],
    }


# ------------------------------------------------------------------ integrity
def _check_integrity(parsed: dict[str, Any]) -> None:
    raw = parsed["raw"]
    unsigned = {key: value for key, value in raw.items() if key != "checksum"}
    if raw["checksum"] != checksum(unsigned):
        raise BackupIntegrity("checksum does not match the backup contents")

    secret = parsed["secret"]
    secret_id = secret["id"]
    current = secret["version"]
    shares = parsed["shares"]
    for share in shares:
        if share["secret_id"] != secret_id:
            raise BackupIntegrity(f"share {share['share_id']} does not belong to secret {secret_id}")
        if share["share_id"] != f"{secret_id}.v{share['version']}.{share['holder']}":
            raise BackupIntegrity(
                f"share {share['share_id']} does not match its secret, version and holder"
            )
        expected = share_commitment(secret_id, share["version"], share["holder"], share["value"])
        if share["commitment"] != expected:
            raise BackupIntegrity(f"share {share['share_id']} value does not match its commitment")

    if {share["version"] for share in shares} != set(range(1, current + 1)):
        raise BackupIntegrity("shares do not cover every version from 1 to the current version")
    roster: dict[int, set[str]] = {}
    for share in shares:
        roster.setdefault(share["version"], set()).add(share["holder"])

    # Role attribution: a v3 document pins the holder and approver rosters of
    # every version; v1/v2 documents are read in legacy mode, where the
    # approvers of a version are exactly its holders.
    versions = parsed["versions"]
    if versions is not None:
        if [entry["version"] for entry in versions] != list(range(1, current + 1)):
            raise BackupIntegrity("versions do not cover every version from 1 to the current version")
        approver_roster: dict[int, set[str]] = {}
        for entry in versions:
            holders = set(entry["holders"])
            approvers = set(entry["approvers"])
            if holders != roster[entry["version"]]:
                raise BackupIntegrity(
                    f"version {entry['version']} holders do not match the shares issued for it"
                )
            if entry["approval_mode"] == "legacy":
                if approvers != holders:
                    raise BackupIntegrity(
                        f"version {entry['version']} is legacy but its approvers differ from its holders"
                    )
            elif holders & approvers:
                raise BackupIntegrity(
                    f"version {entry['version']} approvers overlap its holders"
                )
            approver_roster[entry["version"]] = approvers
    else:
        approver_roster = roster

    for approval in parsed["approvals"]:
        if approval["secret_id"] != secret_id:
            raise BackupIntegrity(f"approval by {approval['approver']} does not belong to secret {secret_id}")
        if not 1 <= approval["version"] <= current:
            raise BackupIntegrity(
                f"approval by {approval['approver']} targets a version outside 1..{current}"
            )
        if approval["approver"] not in approver_roster[approval["version"]]:
            raise BackupIntegrity(
                f"approver {approval['approver']} is not an approver of version {approval['version']}"
            )

    previous = ZERO_HASH
    for index, event in enumerate(parsed["audit_events"], start=1):
        if event["sequence"] != index:
            raise BackupIntegrity("audit events are not an unbroken sequence starting at 1")
        expected = event_hash(
            event["previous_hash"], event["sequence"], event["type"],
            encode(event["payload"]), event["occurred_at"],
        )
        if event["previous_hash"] != previous or event["hash"] != expected:
            raise BackupIntegrity("audit chain hashes do not match the recorded events")
        previous = event["hash"]


def verify(backup: Any) -> dict[str, Any]:
    """Validate a backup document and return a summary of its contents.

    Pure: nothing is read from or written to any service state, and the
    document is either accepted as a whole or rejected as a whole.
    """
    parsed = _parse(backup)
    _check_integrity(parsed)
    secret = parsed["secret"]
    return {
        "valid": True,
        "secret_id": secret["id"],
        "version": secret["version"],
        "share_count": len(parsed["shares"]),
        "approval_count": len(parsed["approvals"]),
        "event_count": len(parsed["audit_events"]),
    }

class ThresholdSafeError(Exception):
    code = "internal_error"
    status = 500


class ValidationError(ThresholdSafeError):
    code = "validation_error"
    status = 400


class NotFoundError(ThresholdSafeError):
    code = "not_found"
    status = 404


class ConflictError(ThresholdSafeError):
    code = "conflict"
    status = 409


class ShareMismatch(ValidationError):
    code = "share_mismatch"


class InsufficientShares(ConflictError):
    code = "insufficient_shares"


class InsufficientApprovals(ConflictError):
    code = "insufficient_approvals"


class StaleShare(ConflictError):
    code = "stale_share"


class ShareNotDistributed(ConflictError):
    code = "share_not_distributed"


class ShareAlreadyDistributed(ConflictError):
    code = "share_already_distributed"


class DuplicateApproval(ConflictError):
    code = "duplicate_approval"


class IntegrityFailure(ConflictError):
    code = "integrity_failure"


class BackupIntegrity(ConflictError):
    code = "backup_integrity"


class SecretFrozen(ConflictError):
    code = "secret_frozen"


class SecretNotFrozen(ConflictError):
    code = "secret_not_frozen"


class PolicyDenied(ConflictError):
    code = "policy_denied"

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Any

from .errors import ValidationError
from .policy import parse_policy
from .shamir import MAX_SECRET_BYTES

IDENTIFIER = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]*$")
SHARE_VALUE = re.compile(r"^[0-9a-f]{1,132}$")

# Marks a rotation body that does not mention policy at all: the stored
# policy is then preserved, while an explicit null clears it.
UNSET: Any = object()


def identifier(value: Any, field: str, limit: int = 100) -> str:
    if not isinstance(value, str) or len(value) > limit or not IDENTIFIER.match(value):
        raise ValidationError(
            f"{field} must start with a letter or digit and contain only letters, digits, dot, "
            f"underscore or dash (at most {limit} characters)"
        )
    return value


def identifier_list(value: Any, field: str) -> list[str]:
    if not isinstance(value, list) or not value:
        raise ValidationError(f"{field} must be a non-empty array of identifiers")
    items = [identifier(entry, f"{field} entry") for entry in value]
    if len(set(items)) != len(items):
        raise ValidationError(f"{field} must not repeat the same identifier")
    return items


def approver_list(value: Any, field: str = "approvers") -> list[str]:
    """A separated approver roster: at least two unique valid identifiers."""
    items = identifier_list(value, field)
    if len(items) < 2:
        raise ValidationError(f"{field} must contain at least two distinct approvers")
    return items


def positive_int(value: Any, field: str, minimum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < minimum:
        raise ValidationError(f"{field} must be an integer greater than or equal to {minimum}")
    return value


def text(value: Any, field: str, limit: int = 200) -> str:
    if not isinstance(value, str) or not value.strip() or len(value) > limit:
        raise ValidationError(f"{field} must be a non-empty string of at most {limit} characters")
    return value


def seed_value(value: Any) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or not 0 <= value <= 2**63:
        raise ValidationError("seed must be an integer between 0 and 2**63")
    return value


def secret_bytes(value: Any) -> bytes:
    if not isinstance(value, str) or value == "":
        raise ValidationError("secret must be a non-empty string")
    data = value.encode("utf-8")
    if len(data) > MAX_SECRET_BYTES:
        raise ValidationError(f"secret must encode to at most {MAX_SECRET_BYTES} bytes")
    return data


def single_field(raw: Any, field: str, description: str) -> str:
    if not isinstance(raw, dict) or set(raw) != {field}:
        raise ValidationError(f"{description} must contain exactly {field}")
    return identifier(raw[field], field)


def reason_field(raw: Any) -> str:
    if not isinstance(raw, dict) or set(raw) != {"reason"}:
        raise ValidationError("freeze request body must contain exactly reason")
    if not isinstance(raw["reason"], str):
        raise ValidationError("reason must be a non-empty string of at most 200 characters")
    reason = raw["reason"].strip()
    if not reason or len(reason) > 200:
        raise ValidationError("reason must be a non-empty string of at most 200 characters")
    return reason


def no_unknown_fields(raw: Any, allowed: set[str], description: str) -> None:
    unknown = sorted(set(raw) - allowed)
    if unknown:
        raise ValidationError(f"{description} does not allow these fields: {', '.join(unknown)}")


@dataclass(frozen=True)
class ShareClaim:
    share_id: str
    value: str


def parse_share_claims(raw: Any) -> list[ShareClaim]:
    if not isinstance(raw, dict) or set(raw) != {"shares"}:
        raise ValidationError("reconstruct body must contain exactly shares")
    entries = raw["shares"]
    if not isinstance(entries, list) or not entries:
        raise ValidationError("shares must be a non-empty array")
    claims: list[ShareClaim] = []
    for entry in entries:
        if not isinstance(entry, dict) or set(entry) != {"share_id", "value"}:
            raise ValidationError("each share must contain exactly share_id and value")
        value = entry["value"]
        if not isinstance(value, str) or not SHARE_VALUE.match(value):
            raise ValidationError("share value must be lowercase hexadecimal of at most 132 characters")
        claims.append(ShareClaim(identifier(entry["share_id"], "share_id", limit=250), value))
    if len({claim.share_id for claim in claims}) != len(claims):
        raise ValidationError("shares must not repeat the same share_id")
    return claims


def resolve_policy(threshold: int, holders: tuple[str, ...], approvals_required: int) -> None:
    resolve_roles(threshold, holders, approvals_required, "legacy", None)


def resolve_roles(
    threshold: int,
    holders: tuple[str, ...],
    approvals_required: int,
    approval_mode: str,
    approvers: tuple[str, ...] | None,
) -> None:
    """Validate one version's threshold, roster and approval quorum.

    In ``legacy`` mode the approvers are the holders, so the quorum is bounded
    by the holder count. In ``separated`` mode the approver roster is explicit:
    it must stay disjoint from the holders and the quorum must allow a genuine
    two-person review without exceeding the roster.
    """
    if threshold > len(holders):
        raise ValidationError("threshold must not exceed the number of holders")
    if approval_mode == "separated":
        assert approvers is not None
        overlap = sorted(set(holders) & set(approvers))
        if overlap:
            raise ValidationError(f"approvers must not overlap holders: {', '.join(overlap)}")
        if not 2 <= approvals_required <= len(approvers):
            raise ValidationError("approvals_required must be between 2 and the number of approvers")
    elif approvals_required > len(holders):
        raise ValidationError("approvals_required must not exceed the number of holders")


@dataclass(frozen=True)
class SecretSpec:
    id: str
    name: str
    threshold: int
    holders: tuple[str, ...]
    approvals_required: int
    secret: bytes
    seed: int | None
    policy: dict[str, Any] | None
    approvers: tuple[str, ...] | None

    @classmethod
    def parse(cls, raw: Any) -> "SecretSpec":
        if not isinstance(raw, dict):
            raise ValidationError("secret definition must be an object")
        required = ["id", "name", "threshold", "holders", "approvals_required", "secret"]
        no_unknown_fields(raw, set(required) | {"seed", "policy", "approvers"}, "secret definition")
        missing = sorted(set(required) - set(raw))
        if missing:
            raise ValidationError(f"missing required fields: {', '.join(missing)}")
        holders = tuple(identifier_list(raw["holders"], "holders"))
        threshold = positive_int(raw["threshold"], "threshold", minimum=2)
        approvals_required = positive_int(raw["approvals_required"], "approvals_required", minimum=1)
        # An explicit approver roster selects the separated mode; omitting the
        # field (or passing null) keeps the legacy holder-as-approver mode.
        approvers = (
            tuple(approver_list(raw["approvers"])) if raw.get("approvers") is not None else None
        )
        resolve_roles(
            threshold,
            holders,
            approvals_required,
            "separated" if approvers is not None else "legacy",
            approvers,
        )
        return cls(
            identifier(raw["id"], "id"),
            text(raw["name"], "name"),
            threshold,
            holders,
            approvals_required,
            secret_bytes(raw["secret"]),
            seed_value(raw["seed"]) if "seed" in raw else None,
            parse_policy(raw["policy"]) if raw.get("policy") is not None else None,
            approvers,
        )


@dataclass(frozen=True)
class RotationSpec:
    """Optional overrides of a rotation; every field defaults to the current value.

    ``policy`` is UNSET when the body omits it (the stored policy is kept),
    None when the body clears it, and a validated expression otherwise.
    ``approvers`` follows the same tri-state: UNSET continues the current
    approval mode (legacy follows the new holders, separated keeps its
    roster), None switches back to legacy, and an array installs or updates
    the separated roster.
    """

    secret: bytes | None
    threshold: int | None
    holders: tuple[str, ...] | None
    approvals_required: int | None
    seed: int | None
    policy: Any
    approvers: Any

    @classmethod
    def parse(cls, raw: Any) -> "RotationSpec":
        if not isinstance(raw, dict):
            raise ValidationError("rotation body must be an object")
        no_unknown_fields(
            raw,
            {"secret", "threshold", "holders", "approvals_required", "seed", "policy", "approvers"},
            "rotation body",
        )
        policy: Any = UNSET
        if "policy" in raw:
            policy = None if raw["policy"] is None else parse_policy(raw["policy"])
        approvers: Any = UNSET
        if "approvers" in raw:
            approvers = None if raw["approvers"] is None else tuple(approver_list(raw["approvers"]))
        return cls(
            secret_bytes(raw["secret"]) if "secret" in raw else None,
            positive_int(raw["threshold"], "threshold", minimum=2) if "threshold" in raw else None,
            tuple(identifier_list(raw["holders"], "holders")) if "holders" in raw else None,
            positive_int(raw["approvals_required"], "approvals_required", minimum=1)
            if "approvals_required" in raw
            else None,
            seed_value(raw["seed"]) if "seed" in raw else None,
            policy,
            approvers,
        )

